export const enc = (q: string) => encodeURIComponent(q);

/**
 * Vibes — caractère stylistique d'une marque (orthogonal au tier prix).
 * Une marque peut porter plusieurs vibes ; on filtre par intersection.
 *
 *   minimal     → ligne pure, palette neutre (COS, Toteme, Lemaire)
 *   old-money   → bourgeoisie discrète (Loro Piana, Khaite, Ralph Lauren)
 *   streetwear  → rue, oversize, hype (Supreme, Stussy, Aimé Leon Dore)
 *   sport-chic  → athleisure premium (Lululemon, Y-3, Stone Island)
 *   avant-garde → créateur conceptuel (Rick Owens, Margiela, Comme des Garçons)
 *   preppy      → collège US (Tommy, Ralph, Lacoste)
 *   bohème      → rêveur, fleuri (Sézane, Free People, Anthropologie)
 *   luxe-max    → logo, opulent (Gucci, LV, Versace)
 */
export type ShopVibe =
  | "minimal" | "old-money" | "streetwear" | "sport-chic"
  | "avant-garde" | "preppy" | "bohème" | "luxe-max";

/** Niveau de prix moyen — pour le filtre budget. */
export type PriceLevel = "budget" | "mid" | "premium" | "luxe";

/**
 * Catégorie de produit qu'une marque vend.
 * Si une marque a un champ `categories` défini, on la considère mono-catégorie
 * et on la filtre quand le `pieceType` ne matche pas (évite d'envoyer chercher
 * des derbies chez Reformation, ou des t-shirts chez Polène).
 * Si le champ est absent, la marque est considérée polyvalente (default).
 */
export type ProductCategory =
  | "tops" | "bottoms" | "dresses" | "knits" | "outerwear"
  | "shoes" | "bags" | "accessories";

/**
 * Mapping piece-slot (Top/Bottom/Shoes/Accent/Outer) → catégories produit acceptables.
 * Si le slot demandé n'est pas dans ce mapping, aucun filtre n'est appliqué.
 */
const PIECE_TYPE_TO_CATEGORIES: Record<string, ProductCategory[]> = {
  Top:    ["tops", "knits", "dresses"],
  Bottom: ["bottoms"],
  Outer:  ["outerwear", "knits"],
  Shoes:  ["shoes"],
  Accent: ["bags", "accessories"],
};

export type ShopLink = {
  label: string;
  sub: string;
  url: string;
  tier: string;
  vibes?: ShopVibe[];     // caractère stylistique
  eco?: boolean;          // engagement durable / certif éco
  priceLevel?: PriceLevel; // prix moyen estimé
  categories?: ProductCategory[]; // si défini → marque mono-catégorie, filtrée selon pieceType
};

/**
 * Pièces ethniques / culturelles que les chaînes Western (H&M, Zara, COS…) ne vendent pas.
 * Pour celles-ci, on bypass le tier mainstream et on route vers Etsy, Vestiaire,
 * 1stDibs, et des recherches Google ciblées sur des boutiques spécialisées.
 */
const ETHNIC_PIECES = /caftan|kaftan|babouche|juttis|sari|saree|huipil|kimono|haori|hakama|kurta|sherwani|sarouel|saroual|guayabera|wax\b|dashiki|kente|berbere|berbère|hanbok|cheongsam|qipao|abaya|thawb|kebaya|poncho|gandoura|djellaba|takchita|haik/i;

