export function scoreDescription(score: number): string {
  if (score === 5) return "Excellence editoriale";
  if (score === 4) return "Tres bon choix";
  if (score === 3) return "Correct";
  if (score === 2) return "Avec precaution";
  return "A eviter si possible";
}
